SourceCode.Declaration:
/// <summary>
/// ATL navigation node for the MD31 item master import, reached as data.md31()
/// through TEST_AtlDataRootNodeMD31_Extension. Groups the factory, query and
/// specification methods for the MD31 tables, as AtlData* nodes do for standard modules.
/// </summary>
public final class TEST_AtlDataMD31 extends AtlDataNode
{
}

Method.Source:
/// <summary>
/// A new, unsaved input row as the file import leaves it: Status New, group 0.
/// The file name doubles as the ExecutionId, which processGroup groups by.
/// </summary>
public TEST_AtlEntityMD31ItemMasterRow initRow(Filename _fileName, SJPMDItemMasterJANCode _skuCode)
{
    return TEST_AtlEntityMD31ItemMasterRow::construct()
        .setFileName(_fileName)
        .setExecutionId(_fileName)
        .setCompanyCode('TEST')
        .setSkuCode(_skuCode)
        .setNameEnglish('MD31 test ' + _skuCode);
}

/// <summary>
/// Writes the MD31 parameters record of the current company (one record per company;
/// SJPMDItemMasterParam::find selects the first). Inside a test it is rolled back.
/// </summary>
public SJPMDItemMasterParam setParameters(
    EcoResStorageDimensionGroupName  _storageGroupName,
    EcoResTrackingDimensionGroupName _trackingGroupName,
    InventModelGroupId               _modelGroupId,
    ItemGroupId                      _itemGroupId,
    UnitIDBase                       _unitId,
    Name                             _nullDateLiteral)
{
    SJPMDItemMasterParam parameters;

    ttsbegin;

    parameters = SJPMDItemMasterParam::find(true);

    parameters.DefaultStorageDimensionGroupName  = _storageGroupName;
    parameters.DefaultTrackingDimensionGroupName = _trackingGroupName;
    parameters.DefaultModelGroupId               = _modelGroupId;
    parameters.DefaultItemGroupId                = _itemGroupId;
    parameters.DefaultUnitIDBase                 = _unitId;
    parameters.NullDateLiteral                   = _nullDateLiteral;
    parameters.DefaultProductType                = EcoResProductType::Item;

    if (parameters.RecId)
    {
        parameters.update();
    }
    else
    {
        parameters.insert();
    }

    ttscommit;

    return parameters;
}
